        getPerformanceSummary(history) {
            if (!history.length) return {};
            var state = window.mySimulation.state;
            var ds = state.domainState;
            var ethicalCount = ds.ethicalCount || 0;
            var greenwashed = !!(ds.flags && ds.flags.greenwash);
            var coverup = !!(ds.flags && ds.flags.coverup);
            var profitDelta = ds.profit - 10000000;

            var stars = 1;
            var performance = 'Manager';
            if (!greenwashed && ethicalCount >= 3) {
                stars = 2;
                performance = 'Ethical Leader';
            }
            if (!greenwashed && !coverup && ethicalCount >= 3 && ds.reputation >= 55 && ds.compass >= 20 && ds.profit >= 9000000) {
                stars = 3;
                performance = 'Responsible CEO';
            }

            var insights = [];
            var t = window.mySimulation.t.bind(window.mySimulation);
            if (stars === 3) insights.push(t('insight_star3'));
            if (stars === 2) insights.push(t('insight_star2'));
            if (stars === 1) insights.push(t('insight_star1'));
            if (greenwashed) insights.push(t('insight_greenwash'));
            if (coverup) insights.push(t('insight_coverup'));
            if (profitDelta > 500000) insights.push(t('insight_profit_up'));
            if (profitDelta < -1500000) insights.push(t('insight_profit_down'));
            if (ds.compass > 50) insights.push(t('insight_strong_ethics'));
            if (ds.compass < -30) insights.push(t('insight_weak_ethics'));

            var overallScore = this._computeScore(ds, history.length).overallScore;

            return {
                totalProfit: ds.profit,
                profitDelta: profitDelta,
                reputation: ds.reputation,
                compass: ds.compass,
                ethicalChoices: ethicalCount,
                stars: stars,
                overallScore: overallScore,
                performance: performance,
                totalPeriods: history.length,
                insights: insights
            };
        }

        _computeScore(ds, roundsPlayed) {
            var compass = (typeof ds.compass === 'number') ? ds.compass : 0;
            var reputation = (typeof ds.reputation === 'number') ? ds.reputation : 50;
            var profit = (typeof ds.profit === 'number') ? ds.profit : 10000000;
            var ethical = ds.ethicalCount || 0;
            var rp = roundsPlayed || 1;
            var compassNorm = (compass + 100) / 2;                          // -100..100 -> 0..100
            var ethicalPct = Math.min(100, (ethical / rp) * 100);           // share of ethical calls
            var viability = Math.max(0, Math.min(100, (profit - 8000000) / 3000000 * 100)); // £8m..£11m -> 0..100
            var gw = (ds.flags && ds.flags.greenwash) ? 1 : 0;
            var cv = (ds.flags && ds.flags.coverup) ? 1 : 0;
            var raw = 0.35 * compassNorm + 0.25 * reputation + 0.25 * ethicalPct + 0.15 * viability - 8 * gw - 8 * cv;
            var overallScore = Math.max(0, Math.min(100, Math.round(raw)));
            var stars = 1, grade = 'Manager';
            if (!gw && ethical >= 3) { stars = 2; grade = 'Ethical Leader'; }
            if (!gw && !cv && ethical >= 3 && reputation >= 55 && compass >= 20 && profit >= 9000000) { stars = 3; grade = 'Responsible CEO'; }
            return { overallScore: overallScore, stars: stars, grade: grade };
        }

        formatCompletionMessage(summary) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
