            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var starRow = '';
            for (var i = 0; i < 3; i++) { starRow += (i < stars ? '★' : '☆'); }
            var tierKey = stars === 3 ? 'perf_ceo' : (stars === 2 ? 'perf_leader' : 'perf_manager');
            var profit = (typeof s.totalProfit === 'number') ? s.totalProfit : 10000000;
            var reputation = (typeof s.reputation === 'number') ? s.reputation : 50;
            var compass = (typeof s.compass === 'number') ? s.compass : 0;
            var ethical = (typeof s.ethicalChoices === 'number') ? s.ethicalChoices : 0;
            var insightsHtml = '';
            if (s.insights && s.insights.length) {
                insightsHtml = '<ul class="ethics-sim-complete-insights">';
                s.insights.forEach(function(ins){ insightsHtml += '<li>' + ins + '</li>'; });
